        return cls(
            revision=data["revision"],
            settings=data["settings"],
            layers=data["layers"],
            styles=data["styles"],
            sheets=data["sheets"],
            data=[AtlasPinLayer.from_json(e0) for e0 in data["data"]],
            digest=data["digest"],
        )


