@dataclass(kw_only=True, slots=True)
class EventLink(_Model):
    """A link: the events of one layer on the routes of some others.
    Attributes:
        id: Letters, digits, `-`, `_`, `.`; 1–64; unique in the project.
        name: What the windows show; trimmed, 1–64 characters.
        events: The event layer's id: the objects it holds are the events (points, or lines and polylines).
        routes: The route layers' ids (1–16, none twice, none the event layer).
        route_field: The routes' id field: a route is the first object of an id.
        event_route: The events' attribute naming their route.
        from_: A line event's from and to measure attributes (`line` only, and then both required).
        measure: A point event's measure attribute (`point` only, and then required).
        offset: The attribute of the offset from the route (m, perpendicular); none: the event is on the route.
        side: The side a positive offset lies on; written only when not `right`.
        tolerance: How far (m) an event may lie from its route's place before a write moves it; none: 0,001. Unit: length.
    """
    id: str
    name: str
    events: str
    kind: EventLinkKind | EventLinkKindName
    routes: list[str]
    route_field: str
    event_route: str
    from_: str | None | Unset = UNSET
    measure: str | None | Unset = UNSET
    offset: str | None | Unset = UNSET
    side: EventSide | EventSideName | Unset = UNSET
    to: str | None | Unset = UNSET
    tolerance: float | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["id"] = self.id
        out["name"] = self.name
        out["events"] = self.events
        out["kind"] = _enum_out(self.kind)
        out["routes"] = list(self.routes)
        out["routeField"] = self.route_field
        out["eventRoute"] = self.event_route
        if self.from_ is not UNSET:
            out["from"] = self.from_
        if self.measure is not UNSET:
            out["measure"] = self.measure
        if self.offset is not UNSET:
            out["offset"] = self.offset
        if self.side is not UNSET:
            out["side"] = _enum_out(self.side)
        if self.to is not UNSET:
            out["to"] = self.to
        if self.tolerance is not UNSET:
            out["tolerance"] = None if self.tolerance is None else float(self.tolerance)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> EventLink:
        return cls(
            id=data["id"],
            name=data["name"],
            events=data["events"],
            kind=_enum_in(EventLinkKind, data["kind"]),
            routes=list(data["routes"]),
            route_field=data["routeField"],
            event_route=data["eventRoute"],
            from_=data.get("from", UNSET),
            measure=data.get("measure", UNSET),
            offset=data.get("offset", UNSET),
            side=_enum_in(EventSide, data["side"]) if "side" in data else UNSET,
            to=data.get("to", UNSET),
            tolerance=UNSET if "tolerance" not in data else None if data["tolerance"] is None else float(data["tolerance"]),
        )


@dataclass(kw_only=True, slots=True)
class ExportAtlas(_Model):
    """Input of `file.export.atlas` v1. Refusals, in order: `invalid_file_path`, `file_exists`, `no_sheets`,
    `unknown_sheet` (`sheet`), `no_atlas`, `atlas_no_layer`, `coverage_not_bound` (`coverage`: `source` for a layer that is
    not bound), `crs_unsupported` (`crs`: a project without a system, a code the registry does not have, a system in
    degrees), `unknown_theme`, `invalid_time`,
    `field_not_found` (`fields[i]`), `atlas_expression`, `atlas_empty`, `pin_mismatch` (`pin`; a conflict: take the plan
    again), `source_changed` (a bound file changed while the pages were made: nothing is written, redo it),
    `pdf_unwritable`, `file_unwritable`. Warnings: `source_stale` (a bound file is not the one its layer was read from:
    the pages are made from the layer, the pinned revision), `source_unsaved` (a bound layer has edits not yet written
    to its file).
    Attributes:
        path: The file to write, an absolute path.
        sheet: The sheet that has the atlas, by id.
        coverage: Where the coverage layer's objects come from: the drawing (the default) or its bound source, whole.
        crs: The coordinate system the pages are drawn in (the EPSG code; absent: the project's). Another than the project's
            is a registry's system in metres the project's moves to (docs/adr/0638 §1): the pages' maps, grids and GeoPDF are
            in it, each page's object fitted on its ground. Unit: epsg.
        drawing: Source drawing path for resolving relative linked images; the native host fills its own file when omitted.
        fields: The attributes the pages may carry, by name; the coverage layer's declared fields when absent (all of an
            undeclared layer's). A field a form marks `redact` is never carried, named or not.
        overwrite: Write over a file that is there.
        pin: The state a plan pinned; the run refuses when the drawing or a bound file is not it.
        theme: A layer state of the project (a theme) that the atlas maps draw instead of the layers they would show.
        time: The moment the temporal layers are shown at (`2024-06-30` or `2024-06-30T12:00`): the coverage layer's objects and the
            maps' drawing are cut by it.
    """
    path: str
    sheet: str
    coverage: AtlasCoverage | AtlasCoverageName | Unset = UNSET
    crs: int | None | Unset = UNSET
    drawing: str | None | Unset = UNSET
    fields: list[str] | None | Unset = UNSET
    overwrite: bool = False
    pin: AtlasPin | None | Unset = UNSET
    theme: str | None | Unset = UNSET
    time: str | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["path"] = self.path
        out["sheet"] = self.sheet
        if self.coverage is not UNSET:
            out["coverage"] = _enum_out(self.coverage)
        if self.crs is not UNSET:
            out["crs"] = self.crs
        if self.drawing is not UNSET:
            out["drawing"] = self.drawing
        if self.fields is not UNSET:
            out["fields"] = None if self.fields is None else list(self.fields)
        out["overwrite"] = self.overwrite
        if self.pin is not UNSET:
            out["pin"] = None if self.pin is None else self.pin.to_json()
        if self.theme is not UNSET:
            out["theme"] = self.theme
        if self.time is not UNSET:
            out["time"] = self.time
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ExportAtlas:
        return cls(
            path=data["path"],
            sheet=data["sheet"],
            coverage=_enum_in(AtlasCoverage, data["coverage"]) if "coverage" in data else UNSET,
            crs=data.get("crs", UNSET),
            drawing=data.get("drawing", UNSET),
            fields=UNSET if "fields" not in data else None if data["fields"] is None else list(data["fields"]),
            overwrite=data["overwrite"] if "overwrite" in data else False,
            pin=UNSET if "pin" not in data else None if data["pin"] is None else AtlasPin.from_json(data["pin"]),
            theme=data.get("theme", UNSET),
            time=data.get("time", UNSET),
        )


