    stretch: RasterStretch | RasterStretchName | Unset = UNSET
    z_factor: float | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["render"] = _enum_out(self.render)
