    length: float
    area: float
    rule: str
    height_from_level: bool | Unset = UNSET
    inner_tread: float | None | Unset = UNSET
    landings: int | Unset = UNSET
    level: str | None | Unset = UNSET
    radius: float | None | Unset = UNSET
    railing_length: float | Unset = UNSET

