@dataclass(kw_only=True, slots=True)
class TimeQueried(_Model):
    """Output of `cad.time.query` v1: the objects shown (persistent ids, in the drawing's order) and why the others are
    not; the moments read, in UTC.
    Attributes:
        not_valid: Objects with a valid time the window does not show. Unit: count.
        not_known: Objects whose version was not known on the day (recorded later, superseded by then, or never recorded). Unit: count.
        timeless: Objects without a valid time (shown: a timeless object shows at every time). Unit: count.
        unrecorded: Objects without a recorded start (with `knownAt` not shown). Unit: count.
        unreadable: Values of the layer's time attributes that are not moments. Unit: count.
        state: The state asked: “Şimdiki hâl”, “1 adım geri, “Taşı” öncesi” or the file's name.
        stamp: The layer's digest in that state (the SHA-256 of its objects' kinds, geometries and attributes by lasting
            id): given back as `expectedStamp`, the same question asks the same data.
        revision: ^(0|[1-9][0-9]*)$
        at: The instant read (`YYYY-MM-DDTHH:MM:SSZ`, a midnight `YYYY-MM-DD`).
    """
    layer: str
    shown: list[str]
    not_valid: int
    not_known: int
    timeless: int
    unrecorded: int
    unreadable: int
    state: str
    stamp: str
    revision: str
    at: str | None | Unset = UNSET
    from_: str | None | Unset = UNSET
    known_at: str | None | Unset = UNSET
    to: str | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["layer"] = self.layer
        out["shown"] = list(self.shown)
        out["notValid"] = self.not_valid
        out["notKnown"] = self.not_known
        out["timeless"] = self.timeless
        out["unrecorded"] = self.unrecorded
        out["unreadable"] = self.unreadable
        out["state"] = self.state
        out["stamp"] = self.stamp
        out["revision"] = self.revision
        if self.at is not UNSET:
            out["at"] = self.at
        if self.from_ is not UNSET:
            out["from"] = self.from_
        if self.known_at is not UNSET:
            out["knownAt"] = self.known_at
        if self.to is not UNSET:
            out["to"] = self.to
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> TimeQueried:
        return cls(
            layer=data["layer"],
            shown=list(data["shown"]),
            not_valid=data["notValid"],
            not_known=data["notKnown"],
            timeless=data["timeless"],
            unrecorded=data["unrecorded"],
            unreadable=data["unreadable"],
            state=data["state"],
            stamp=data["stamp"],
            revision=data["revision"],
            at=data.get("at", UNSET),
            from_=data.get("from", UNSET),
            known_at=data.get("knownAt", UNSET),
            to=data.get("to", UNSET),
        )


@dataclass(kw_only=True, slots=True)
class TimeQuery(_Model):
    """Input of `cad.time.query` v1. Refusals: `no_such_step`, `invalid_file_path`, `file_not_found`, `import_unreadable`
    (the state asked), `layer_not_found`, `not_a_layer`, `not_temporal`, `invalid_moment`, `invalid_period`,
    `not_recorded`; the conflict `state_changed` (docs/adr/0646 §1).
    Attributes:
        layer: The temporal layer's id.
        at: The valid time's instant; with `from` and `to` refused.
        expected_stamp: The layer's digest a former answer gave (`stamp`): the state must hold the layer as it did, else
            `state_changed`.
        from_: The valid time's period [from, to): both or neither.
        known_at: The day known: only the versions recorded by then and not yet superseded (a layer that records them).
        revision: The state asked (docs/adr/0646 §1): the drawing some undo steps back or a drawing file; none, the drawing as
            it is.
    """
    layer: str
    at: str | None | Unset = UNSET
    expected_stamp: str | None | Unset = UNSET
    from_: str | None | Unset = UNSET
    known_at: str | None | Unset = UNSET
    revision: CompareAgainst | None | Unset = UNSET
    to: str | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["layer"] = self.layer
        if self.at is not UNSET:
            out["at"] = self.at
        if self.expected_stamp is not UNSET:
            out["expectedStamp"] = self.expected_stamp
        if self.from_ is not UNSET:
            out["from"] = self.from_
        if self.known_at is not UNSET:
            out["knownAt"] = self.known_at
        if self.revision is not UNSET:
            out["revision"] = None if self.revision is None else self.revision.to_json()
        if self.to is not UNSET:
            out["to"] = self.to
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> TimeQuery:
        return cls(
            layer=data["layer"],
            at=data.get("at", UNSET),
            expected_stamp=data.get("expectedStamp", UNSET),
            from_=data.get("from", UNSET),
            known_at=data.get("knownAt", UNSET),
            revision=UNSET if "revision" not in data else None if data["revision"] is None else CompareAgainst.from_json(data["revision"]),
            to=data.get("to", UNSET),
        )


@dataclass(kw_only=True, slots=True)
class TimeVersion(_Model):
    """`cad.time.version`'s input.

    Refusals, in this order: `no_entities`, `invalid_uid`, `invalid_moment`, `invalid_revision`, `revision_conflict`,
    `entity_not_found`; then every object in the input's order: `not_ranged`, `layer_locked`, `time_unreadable`,
    `not_versionable` (Yeni sürüm oluştur: a record or an architectural object, copied by their own commands); then
    `not_within`, which names the first object whose time does not hold the date and counts them all; then
    `invalid_attribute`, a typed end field (or, for the new versions, start field) that does not take the date as its
    text. The new versions are written as `cad.entities.create` writes them, by their layer's fields and rules.
    Attributes:
        uids: The objects' persistent ids, at least one; a repeat counts once.
        at: The date: a date (`2024-03-05`, `05.03.2024`), or a date and a time with an optional zone (`2024-03-05T10:30`,
            `2024-03-05T10:30:00+03:00`; without a zone UTC), as the layers' attributes are read (ADR 0210 §3).
    """
    uids: list[str]
    at: str
    expected_revision: str | None | Unset = UNSET
    kind: TimeVersionKind | TimeVersionKindName = TimeVersionKind.VERSION

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["uids"] = list(self.uids)
        out["at"] = self.at
        if self.expected_revision is not UNSET:
            out["expectedRevision"] = self.expected_revision
        out["kind"] = _enum_out(self.kind)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> TimeVersion:
        return cls(
            uids=list(data["uids"]),
            at=data["at"],
            expected_revision=data.get("expectedRevision", UNSET),
            kind=_enum_in(TimeVersionKind, data["kind"]) if "kind" in data else TimeVersionKind.VERSION,
        )


