    measure: float | None | Unset = UNSET
    measure_kind: str | None | Unset = UNSET
    outside: list[str] | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["key"] = self.key
        out["rule"] = self.rule
