@dataclass(kw_only=True, slots=True)
class MirrorTransform(Transform):
    """Mirror (aynala) across the line through `a` and `b`, two different points. `text` is what becomes of the
    texts (docs/adr/0292, AutoCAD's MIRRTEXT): readable (the default) or mirrored. A text's words and a block's
    attribute values never change; a block's own texts and attributes always read upright.
    Attributes:
        a: Unit: length.
        b: Unit: length.
    """
    TAG_VALUE: ClassVar[str] = "mirror"
    a: Vec2
    b: Vec2
    text: MirrorText | MirrorTextName | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "mirror"}
        out["a"] = _vec2_out(self.a)
        out["b"] = _vec2_out(self.b)
        if self.text is not UNSET:
            out["text"] = None if self.text is None else _enum_out(self.text)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> MirrorTransform:
        return cls(
            a=Vec2.from_json(data["a"]),
            b=Vec2.from_json(data["b"]),
            text=UNSET if "text" not in data else None if data["text"] is None else _enum_in(MirrorText, data["text"]),
        )


@dataclass(kw_only=True, slots=True)
class AlignTransform(Transform):
    """Align (hizala, AutoCAD's ALIGN): `source` goes onto `target`. With a
    second pair (`source2` and `target2`, given together) the objects
    also turn about `source` so that the direction from `source` to
    `source2` lies along the one from `target` to `target2`, and with
    `scale` they are scaled about it so that the one length becomes the
    other. The second pair's points must lie apart from the first's;
    `scale` means nothing without a second pair.
    Attributes:
        source: Unit: length.
        target: Unit: length.
        source2: Unit: length.
        target2: Unit: length.
    """
    TAG_VALUE: ClassVar[str] = "align"
    source: Vec2
    target: Vec2
    scale: bool | None | Unset = UNSET
    source2: Vec2 | None | Unset = UNSET
    target2: Vec2 | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "align"}
        out["source"] = _vec2_out(self.source)
        out["target"] = _vec2_out(self.target)
        if self.scale is not UNSET:
            out["scale"] = self.scale
        if self.source2 is not UNSET:
            out["source2"] = None if self.source2 is None else _vec2_out(self.source2)
        if self.target2 is not UNSET:
            out["target2"] = None if self.target2 is None else _vec2_out(self.target2)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> AlignTransform:
        return cls(
            source=Vec2.from_json(data["source"]),
            target=Vec2.from_json(data["target"]),
            scale=data.get("scale", UNSET),
            source2=UNSET if "source2" not in data else None if data["source2"] is None else Vec2.from_json(data["source2"]),
            target2=UNSET if "target2" not in data else None if data["target2"] is None else Vec2.from_json(data["target2"]),
        )


@dataclass(kw_only=True, slots=True)
class SimilarityTransform(Transform):
    """Oturt (docs/adr/0156): a similarity between centred frames, `from`
    the source centre, `to` the target's: x′ = to.x + a·x̄ − b·ȳ,
    y′ = to.y + b·x̄ + a·ȳ, x̄ = x − from.x, ȳ = y − from.y. Every kind
    moves as the modify tools move it.
    Attributes:
        from_: Unit: length.
        to: Unit: length.
        a: Unit: 1.
        b: Unit: 1.
    """
    TAG_VALUE: ClassVar[str] = "similarity"
    from_: Vec2
    to: Vec2
    a: float
    b: float

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "similarity"}
        out["from"] = _vec2_out(self.from_)
        out["to"] = _vec2_out(self.to)
        out["a"] = float(self.a)
        out["b"] = float(self.b)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> SimilarityTransform:
        return cls(
            from_=Vec2.from_json(data["from"]),
            to=Vec2.from_json(data["to"]),
            a=float(data["a"]),
            b=float(data["b"]),
        )


@dataclass(kw_only=True, slots=True)
class AffineTransform(Transform):
    """Oturt: an affine transform between centred frames, `m` = [a, b, c, d]:
    x′ = to.x + a·x̄ + c·ȳ, y′ = to.y + b·x̄ + d·ȳ. Not a similarity: a
    circle, an arc or an ellipse becomes the ellipse of its image (an
    object may change its kind), a path's arc segments straight vertices
    within 0.1 mm; texts, notes, blocks, dimensions and hatch patterns
    keep their shape at their anchor (docs/adr/0156 §4, §5).
    Attributes:
        from_: Unit: length.
        to: Unit: length.
        m: Unit: 1.
    """
    TAG_VALUE: ClassVar[str] = "affine"
    from_: Vec2
    to: Vec2
    m: list[float]

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "affine"}
        out["from"] = _vec2_out(self.from_)
        out["to"] = _vec2_out(self.to)
        out["m"] = [float(e0) for e0 in self.m]
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> AffineTransform:
        return cls(
            from_=Vec2.from_json(data["from"]),
            to=Vec2.from_json(data["to"]),
            m=[float(e0) for e0 in data["m"]],
        )


@dataclass(kw_only=True, slots=True)
class ProjectiveTransform(Transform):
    """Oturt: a projective transform between centred frames, `h` = [a1, a2,
    a3, b1, b2, b3, c1, c2]: w = c1·x̄ + c2·ȳ + 1, x′ = to.x + (a1·x̄ +
    a2·ȳ + a3)/w, y′ = to.y + (b1·x̄ + b2·ȳ + b3)/w. Lines stay straight;
    curves become straight vertices within 0.1 mm; a point where w is
    1e-9 or less lies beyond the horizon.
    Attributes:
        from_: Unit: length.
        to: Unit: length.
        h: Unit: 1.
    """
    TAG_VALUE: ClassVar[str] = "projective"
    from_: Vec2
    to: Vec2
    h: list[float]

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "projective"}
        out["from"] = _vec2_out(self.from_)
        out["to"] = _vec2_out(self.to)
        out["h"] = [float(e0) for e0 in self.h]
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ProjectiveTransform:
        return cls(
            from_=Vec2.from_json(data["from"]),
            to=Vec2.from_json(data["to"]),
            h=[float(e0) for e0 in data["h"]],
        )


@dataclass(kw_only=True, slots=True)
class RubbersheetTransform(Transform):
    """Kauçuk levha (docs/adr/0158): the thin plate spline of the links'
    displacements, through every link exactly (a link whose `to` is its
    `from` holds its point), following their affine trend far from them.
    Only vertices move: straight edges stay straight, an arc segment keeps
    its bulge; a circle, an arc and an ellipse move by the nearest
    similarity at their centre; texts, notes, blocks, dimensions and hatch
    patterns keep their shape at their anchor. 3 to 1000 links, their
    sources apart and not all on one line.
    """
    TAG_VALUE: ClassVar[str] = "rubbersheet"
    links: list[RubberLink]

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "rubbersheet"}
        out["links"] = [e0.to_json() for e0 in self.links]
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> RubbersheetTransform:
        return cls(
            links=[RubberLink.from_json(e0) for e0 in data["links"]],
        )


@dataclass(kw_only=True, slots=True)
class ArrangeTransform(Transform):
    """Hizala ve dağıt (docs/adr/0194): each object moves on its own along
    one axis. The six alignments put its box's west side (`left`),
    middle (`center`) or east side (`right`) on the easting `at`, its
    north side (`top`), middle (`middle`) or south side (`bottom`) on
    the northing `at`; the two spreads (`horizontal`, `vertical`) keep
    the first and the last box by their middles and space the others
    at equal gaps between them, `at` not given. A box is the object's
    extent as the drawing measures it (an insert with its block's
    pieces, a text in the drawing's typeface).
    Attributes:
        at: Unit: length.
    """
    TAG_VALUE: ClassVar[str] = "arrange"
    mode: ArrangeMode | ArrangeModeName
    at: float | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "arrange"}
        out["mode"] = _enum_out(self.mode)
        if self.at is not UNSET:
            out["at"] = None if self.at is None else float(self.at)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ArrangeTransform:
        return cls(
            mode=_enum_in(ArrangeMode, data["mode"]),
            at=UNSET if "at" not in data else None if data["at"] is None else float(data["at"]),
        )


